<script>
 import { formatDuration,pages } from './windows11-clock.js';
 let {native,execute}=$props();const state=$derived(native.apps.clock);
 const send=(name,payload={},target={})=>execute({command:`win11.clock.${name}`,target,payload});
 const names={timer:'Timer',alarms:'Alarm',stopwatch:'Stopwatch'};
 const scroll=event=>execute({command:'win11.apps.scroll.observe',target:{appId:'clock',area:'clock-content'},payload:{top:event.currentTarget.scrollTop,left:event.currentTarget.scrollLeft}});
</script>
<section class="clock"><aside class="w11-app-sidebar" inert={state.ui.dialog!==null}><h3>Clock</h3>{#each pages as page}<button data-control={`clock-page-${page}`} class:selected={state.page===page} onclick={()=>send('page',{}, {page})}>{page==='timer'?'◴':page==='alarms'?'◷':'◉'}　{names[page]}</button>{/each}<p>Fictional scene<br /><strong>{formatDuration(state.sceneSeconds%86400)}</strong><br />Tuesday, October 31</p></aside><main inert={state.ui.dialog!==null} data-area="clock-content" onscroll={scroll}><header><h2>{names[state.page]}</h2><button data-control="clock-options" aria-label="Clock options" onclick={()=>execute({command:'win11.apps.menu',target:{appId:'clock'},payload:{menu:state.ui.menu?null:'options'}})}>···</button></header>
 {#if state.ui.menu}<div class="w11-app-menu"><p>Local scene clock. No system time, audio or notifications are changed.</p><button data-control="clock-close-menu" onclick={()=>execute({command:'win11.apps.menu',target:{appId:'clock'},payload:{menu:null}})}>Close</button></div>{/if}
 {#each state.notifications as notice}<div class="notification" role="status"><strong>{notice.label}</strong><button data-control={`clock-dismiss-${notice.id}`} onclick={()=>send('dismiss',{}, {notificationId:notice.id})}>Dismiss</button></div>{/each}
 {#if state.page==='timer'}<article class="timer-card"><h3>{state.timer.name}</h3><div class="dial"><strong>{formatDuration(state.timer.remaining)}</strong></div><div class="actions"><button class="primary" data-control="clock-timer-toggle" disabled={!state.timer.running&&state.timer.remaining===0} onclick={()=>send('timer',{action:state.timer.running?'pause':'start'})}>{state.timer.running?'Ⅱ Pause':'▶ Start'}</button><button data-control="clock-timer-reset" onclick={()=>send('timer',{action:'reset'})}>↺ Reset</button><button data-control="clock-timer-edit" disabled={state.timer.running} onclick={()=>send('dialog',{kind:'timer'})}>Edit timer</button></div></article>
 {:else if state.page==='alarms'}<p class="muted">Alarms follow fictional scene time, not your device clock.</p><div class="alarms">{#each state.alarms as alarm}<article><button class="alarm-time" data-control={`clock-edit-${alarm.id}`} onclick={()=>send('editAlarm',{}, {alarmId:alarm.id})}>{alarm.time}</button><div>{alarm.name}</div><p>Every day</p><label><input type="checkbox" data-control={`clock-alarm-${alarm.id}`} checked={alarm.enabled} onchange={event=>send('alarmSet',{enabled:event.currentTarget.checked},{alarmId:alarm.id})} />{alarm.enabled?'On':'Off'}</label><button data-control={`clock-delete-${alarm.id}`} onclick={()=>send('alarmDelete',{}, {alarmId:alarm.id})}>Delete</button></article>{/each}</div><button class="primary" data-control="clock-add-alarm" onclick={()=>send('dialog',{kind:'alarm'})}>＋ Add an alarm</button>
 {:else}<div class="stopwatch"><strong>{formatDuration(state.stopwatch.elapsed)}</strong><div class="actions"><button class="primary" data-control="clock-stopwatch-toggle" onclick={()=>send('stopwatch',{action:state.stopwatch.running?'pause':'start'})}>{state.stopwatch.running?'Ⅱ Pause':'▶ Start'}</button><button data-control="clock-stopwatch-lap" disabled={!state.stopwatch.running} onclick={()=>send('stopwatch',{action:'lap'})}>⚑ Lap</button><button data-control="clock-stopwatch-reset" onclick={()=>send('stopwatch',{action:'reset'})}>↺ Reset</button></div></div><table><thead><tr><th>Lap</th><th>Split</th><th>Total</th></tr></thead><tbody>{#each state.stopwatch.laps as lap,i}<tr><td>{state.stopwatch.laps.length-i}</td><td>{formatDuration(lap.split)}</td><td>{formatDuration(lap.elapsed)}</td></tr>{/each}</tbody></table>{/if}
 </main>{#if state.ui.dialog&&state.draft}<div class="scrim" role="dialog" aria-modal="true" aria-label={state.ui.dialog==='alarm'?'Edit alarm':'Edit timer'}><section class="w11-app-dialog"><h2>{state.ui.dialog==='alarm'?'Alarm':'Timer'}</h2><label>Name<input class="w11-app-input" data-control="clock-draft-name" value={state.draft.name} oninput={event=>send('draft',{value:event.currentTarget.value},{field:'name'})} /></label>{#if state.ui.dialog==='alarm'}<label>Time (24-hour)<input type="time" data-control="clock-draft-time" value={state.draft.time} oninput={event=>send('draft',{value:event.currentTarget.value},{field:'time'})} /></label>{:else}<label>Duration in seconds<input type="number" min="1" max="359999" data-control="clock-draft-duration" value={state.draft.duration} oninput={event=>send('draft',{value:event.currentTarget.value},{field:'duration'})} /></label>{/if}<p class="muted">{state.ui.dialog==='alarm'?'Use a valid 24-hour time.':'Choose 1–359999 seconds.'} Name is required.</p><div class="actions"><button class="primary" data-control="clock-save" onclick={()=>send('save')}>Save</button><button data-control="clock-cancel" onclick={()=>send('dialog',{kind:'none'})}>Cancel</button></div></section></div>{/if}</section>
<style>
 .clock{height:100%;display:flex;position:relative;background:var(--w11-theme-surface,#f9f9f9);color:var(--w11-theme-text,#242424)}.clock aside{width:155px;flex-shrink:0;background:var(--w11-theme-chrome,#f1f1f1);padding:16px 8px}.clock aside button{width:100%;text-align:left;margin:4px 0}.clock button{border:1px solid var(--w11-theme-border,#ddd);background:var(--w11-theme-card,white);border-radius:5px;padding:9px 13px;color:inherit;cursor:pointer}.clock button:hover{background:var(--w11-theme-hover,#eee)}.clock button:disabled{opacity:.4;cursor:default}.clock aside .selected{background:var(--w11-theme-selection,#e4e4e4);border-left:3px solid var(--w11-accent,#0078d4)}aside p{font-size:12px;color:var(--w11-theme-muted,#666);margin:40px 8px}aside strong{font-size:20px;font-weight:400;color:var(--w11-theme-text,#333)}main{padding:22px;overflow:auto;flex:1;min-width:0}header{display:flex;justify-content:space-between;align-items:center}h2{font-size:26px;font-weight:600;margin:0 0 20px}.timer-card{border:1px solid var(--w11-theme-border,#e1e1e1);border-radius:8px;background:var(--w11-theme-card,white);padding:18px;text-align:center}.timer-card h3{text-align:left;font-weight:500}.dial{width:220px;height:220px;border:5px solid var(--w11-accent,#0078d4);border-radius:50%;display:grid;place-items:center;margin:20px auto}.dial strong{font-size:36px;font-weight:400;font-variant-numeric:tabular-nums}.actions{display:flex;gap:8px;justify-content:center;flex-wrap:wrap}.clock .primary{background:var(--w11-accent,#0078d4);color:white;border-color:transparent}.alarms{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:15px;margin-bottom:20px}.alarms article{padding:18px;border:1px solid var(--w11-theme-border,#ddd);background:var(--w11-theme-card,white);border-radius:8px}.clock .alarm-time{font-size:36px;border:0;padding:0;margin-bottom:10px}.alarms label{margin-right:15px}.muted{font-size:12px;color:var(--w11-theme-muted,#666)}.stopwatch{text-align:center;padding:40px 0}.stopwatch>strong{font-size:52px;font-weight:300;display:block;margin-bottom:30px}table{width:100%;border-collapse:collapse}th,td{padding:10px;text-align:left;border-bottom:1px solid var(--w11-theme-border,#ddd);font-variant-numeric:tabular-nums}.notification{padding:15px;background:var(--w11-theme-selection,#e7f2ff);border-radius:6px;margin:12px 0;display:flex;align-items:center;gap:15px}.scrim{position:absolute;inset:0;background:#0004;display:grid;place-items:center;padding:12px}.scrim section{width:min(340px,100%);background:var(--w11-theme-chrome,#fafafa);border-radius:8px;padding:24px;box-shadow:0 10px 40px #0004}.scrim label{display:flex;flex-direction:column;gap:6px;margin:15px 0}.scrim input{padding:10px;border:1px solid var(--w11-theme-border,#aaa);border-radius:4px;background:var(--w11-theme-card,white)}@media(max-width:540px){.clock aside{width:105px;padding:10px 4px}.clock aside button{padding:9px 3px;font-size:12px}main{padding:12px}.dial{width:160px;height:160px}.dial strong{font-size:27px}.stopwatch>strong{font-size:34px}}
 @media(max-width:540px){.timer-card{padding:10px}.dial{width:min(160px,100%);height:auto;aspect-ratio:1;box-sizing:border-box}.dial strong{font-size:clamp(18px,4vw,27px)}.alarms{grid-template-columns:repeat(auto-fit,minmax(min(180px,100%),1fr))}.stopwatch>strong{font-size:clamp(22px,7vw,34px)}.notification{flex-wrap:wrap}th,td{padding:6px;font-size:12px}}
</style>
